P = [
 dict(pmid='43057012', doi='10.1016/j.jhazmat.2026.144238', journal='J Hazard Mater', title='Post-operative exposure to air pollution and colorectal cancer survival: A multi-center cohort study in southwestern China.', tier='A', basis='Model (CTM / LUR / ML)', short='Chongqing 7068 post-resection CRC patients: PM2.5 HR 1.079 per 5 ug/m3 for all-cause death; organic matter the consistent constituent', design='Cohort', pm='CHAP residential PM2.5, PM10 and gases; TAP PM2.5 constituents (SO4, NO3, NH4, OM, BC); 1-year lagged moving averages, time-varying', geo='China (Chongqing)', endpoint='All-cause mortality after radical colorectal cancer resection', affil='First Affiliated Hospital of Chongqing Medical University, China; First Affiliated Hospital of Chongqing Medical University, China', n='7,068 patients after radical colorectal cancer resection at four Chongqing hospitals, median follow-up 56 months, 1,540 deaths; residential CHAP PM2.5, PM10 and gases and TAP PM2.5 constituents; time-varying Cox models on 1-year lagged moving averages. Per 5 ug/m3, HR 1.079 (95% CI 1.045-1.115) for PM2.5 and 1.050 (1.027-1.074) for PM10, stable in two-pollutant and sensitivity models. Organic matter was the most consistent constituent (HR per IQR 1.088, 1.028-1.152), robust in residual and remaining-mass models; O3 was inversely associated. Weakness: all-cause rather than CRC-specific death, residence at diagnosis only, and stage and treatment can be confounded by hospital catchment; constituent surfaces are model products with correlated errors. Relevance: the OM signal argues for organic-aerosol-sensitive monitoring, which optical mass sensors do not resolve.', sub=corpus.OTHR),
 dict(pmid='43056200', doi='10.1093/eurjpc/zwag595', journal='Eur J Prev Cardiol', title='Blood pressure and arterial stiffness in the pathway between long-term PM2.5 exposure and cardiovascular risk: exploratory mediation analysis in middle-aged and older adult men.', tier='A', basis='Model (CTM / LUR / ML)', short='Varese RoCAV men: +151 MACE per 100,000 p-y per 1 ug/m3 PM2.5, 32% mediated by carotid-femoral pulse wave velocity', design='Prospective cohort', pm='12-month mean residential PM2.5 before baseline from EXPANSE models; per 1 ug/m3', geo='Italy (Varese)', endpoint='Incident major acute CHD or stroke (MACE); mediation by blood pressure and cfPWV', affil='University of Insubria, Italy; University of Insubria, Italy', n='2,119 men aged 50-75 free of CHD and stroke in the Varese RoCAV cohort, cfPWV measured in 1,015; 12-month pre-baseline PM2.5 from EXPANSE models; median follow-up 7.6 years, 178 MACE; marginal structural and Aalen models. Each 1 ug/m3 PM2.5 was associated with 151 (95% CI 21-282) additional MACE per 100,000 person-years, 48 (17-79) of them mediated by cfPWV (32%); systolic BP and pulse pressure each mediated about 16%. The cfPWV-mediated excess was larger with impaired glucose (96, 38-155) and raised LDL (88, 28-147). Weakness: men only, one year of exposure, mediators measured at baseline alongside exposure so temporal ordering is assumed, and wide CIs from 178 events. Relevance: arterial stiffness as a measurable intermediate makes smaller sensor-based exposure cohorts feasible.', sub=corpus.CVM),
 dict(pmid='', doi='10.5194/amt-19-7607-2026', journal='Atmospheric Measurement Techniques', title='Harmonizing measurements of oxidative potential of PM: an interlaboratory comparison of the ascorbic acid assay', tier='A', basis='Lab / research instrument', short='26-laboratory comparison of ascorbic-acid oxidative potential: repeatable within labs, significant between-lab discrepancies, just over half satisfactory', design='Analytical method validation', pm='Four PM filter samples and one chemical standard; simplified OP-AA protocol covering extraction to calculation', geo='Global / multi-region', endpoint='Inter-laboratory agreement of OP-AA measurements', affil='Universite Grenoble Alpes, CNRS, IGE, France; Universite Grenoble Alpes, CNRS, IGE, France', n='Second international oxidative-potential inter-laboratory comparison, after the 2023 DTT exercise: 26 laboratories measured ascorbic-acid OP (OP-AA) on four PM filter samples and one chemical compound with a simplified protocol covering the whole chain including extraction. Most laboratories were internally repeatable, but between-laboratory discrepancies were significant; just over half achieved satisfactory results, which the authors take as evidence the protocol is fit for large-scale use. Technical, analytical and calculation refinements are also tested. Weakness: the abstract gives no z-scores, between-laboratory CVs or magnitude of the discrepancies, and four samples span a limited OP range. Relevance: OP is now a recommended monitoring metric in the revised EU Air Quality Directive; harmonised AA and DTT protocols are the precondition for validating any sensor-based or proxy OP estimate.', sub=corpus.SENS),
 dict(pmid='43057505', doi='10.1016/j.ajo.2026.11.011', journal='Am J Ophthalmol', title="Smoke, Not Smoking, as a Possible Risk Factor Triggering Conversion in Leber's Hereditary Optic Neuropathy: A Retrospective Case Series.", tier='B', basis='Proxy / questionnaire', short='LHON carriers in Northern California wildfire smoke: 7/9 converted vs 8/31 elsewhere (OR 10.1, p=0.02); four cases 4-8 weeks post-fire', design='Retrospective clinical series', pm='Wildfire smoke assigned by region of residence and multi-day AQI >150 (2017 Wine Country, 2018 Camp Fire); no individual PM2.5', geo='USA (California)', endpoint='Conversion of LHON mutation carriers to symptomatic bilateral vision loss', affil='Doheny Eye Institute, USA; David Geffen School of Medicine at UCLA, USA', n='Retrospective case series plus exploratory registry analysis. Four genetically confirmed LHON carriers developed bilateral vision loss 4-8 weeks after the 2017 Wine Country and 2018 Camp Fire smoke episodes, all living where AQI exceeded 150 for consecutive days; two had been asymptomatic for over four decades. In the 40-carrier registry, conversion in 2017-2018 was 7/9 (78%) in the wildfire-affected region vs 8/31 (26%) elsewhere (OR 10.1, Fisher p=0.02, no CI); within 8 weeks of the Camp Fire, 3/5 vs 0/23. Weakness: tiny numbers, region of residence as the only exposure, and a 26% background conversion in two years far above usual LHON penetrance suggests registry selection. Relevance: a mitochondrial-susceptibility signal that would need individual smoke PM2.5 to test - the use case for dense sensor networks during fires.', sub=corpus.OTHR),
]
